sketches.source:
setcpm(48/4)

// The sea far above you, muffled by fathoms of water
surface: s("surf").slow(8).intensity(.5).elevation(70).distance(10).occlude(.7).gain(.2)

// The city's hum: 0 degrees sits in the centre of your head, 90 loosens, 180 spreads into the stone
// On speakers the 180-degree bars nearly vanish
city: note("[c1,g1,db2]").s("sawtooth").lpf(400).iphase("<0 0 90 90 180 180 90 90>")
  .attack(3).sustain(1).release(4).gain(.2)

// Cyclopean masonry shifting: a creak from a new and wrong angle every bar
masonry: s("~ ~ creak ~").speed(.5).azimuth("<-120 60 150 -30 90 -150 30 180>")
  .elevation("<-20 10 -40 0 20 -10 -30 40>").distance(5).space("church").gain(.14)

// Bubbles rising from the doors of the tomb, below and around you
bubbles: s("drip*8?0.5").speed(rand.range(.3, .8)).azimuth(rand.range(-180, 180))
  .elevation(rand.range(-60, 0)).distance(rand.range(1, 4)).seed("rlyeh").gain(.12)

// A choir of the drowned, singing through the stone: Cm, Db, Ab, G
choir: note("<[c3,eb3,g3] [db3,f3,ab3] [ab2,c3,eb3] [g2,b2,d3]>").slow(2)
  .s("choir").syl("<oo oh oo ah>").occlude(.6).attack(3).release(4).space("church").gain(.22)

setcpm(60/4)

// The noise of the deep: the same white noise feeds both ears, but one ear is phase-shifted in a narrow band
// Neither ear alone hears a tone; together they hear the call
call: s("white*4").dichotic("<[294 311 349 311] [294 262 233 262] [349 392 440 392] [311 294 311 294]>")
  .dichoticq(30).attack(.03).sustain(1).release(.08).gain(.14)

// A quiet hint: the first bar hummed, once every four bars
hint: note("<[d4 eb4 f4 eb4] ~ ~ ~>").s("hum").attack(.05).release(.3).gain(.07)

// Whispers circling your head once every four bars: the words nobody should say aloud
whispers: s("whisper*4?0.6").syl("<[i_a i_a ka thu] [fa tag loo ah]>").hpf(800)
  .azimuth(saw.range(-180, 180).slow(4)).distance(1.5).posglide(.3).seed("call").gain(.08)

// The sea, and a low drone from far below
sea: s("surf").slow(8).intensity(.3).distance(6).gain(.14)
drone: note("[d1,a1]").slow(8).s("sine").attack(4).sustain(1).release(6).gain(.2)

setcpm(44/4)

// The abyss: a 2 Hz binaural drone, each ear detuned by 1 Hz, below the 3-30 Hz warning range
abyss: note("<d1 d1 bb0 c1>").slow(2).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.26)

// The surface, far above and muffled by the water
surface: s("surf").slow(8).intensity(.4).elevation(70).distance(10).occlude(.7).gain(.18)

// Father Dagon circles slowly beneath you, once every sixteen bars, gliding from note to note
dagon: note("<[d2@2 a1@6] ~ [f2@3 eb2@5] ~>").s("sawtooth").mono(1).glide(.5).vowel("oo")
  .lpf(600).attack(.5).sustain(.8).release(2)
  .azimuth(saw.range(-180, 180).slow(16)).elevation(-40).distance(8).posglide(1).space("hall").gain(.22)

// The Deep Ones hum in the dark: irate turns the phase between the ears, all below 3 Hz
deepones: note("[d3,a3]").s("sine").timbre("hollow").irate("<.25 .5 1 .5>")
  .attack(2).sustain(1).release(2).gain(.12)

// Bubbles drifting up past your ears
bubbles: s("drip*8?0.4").speed(rand.range(.3, .7)).azimuth(rand.range(-180, 180))
  .elevation(rand.range(-40, 40)).distance(2).seed("innsmouth").gain(.12)

setcpm(60/4)

// A colour no eye has seen: bells whose partials are all shifted by the same hertz, so no key survives
bells: note("<c5 ~ gb5 ~ a4 ~ eb5 ~>").s("sine").fm(3).fmh(1.41).fshift("<0 47 -91 133>")
  .decay(3).sustain(0).release(3)
  .azimuth(rand.range(-150, 150)).elevation(30).distance(3).seed("meteor").space("hall").gain(.12)

// The blight spreads: earsh raises the right ear and lowers the left, wider every two bars
// 4 cents beats slowly; 60 cents is two different worlds, one in each ear
blight: note("[c3,gb3,b3]").s("sawtooth").unison(2).detune(.1).earsh("<4 4 12 12 30 30 60 60>")
  .lpf(1100).attack(2).sustain(1).release(3).gain(.12)

// The well hums, ring-modulated into something wrong
well: note("c2").slow(4).s("sine").ringmod(sine.range(20, 90).slow(8)).ringmix(.5)
  .attack(3).sustain(1).release(4).gain(.16)

// Grey dust in the air: unrelated noise in each ear, wide and everywhere
dust: s("pink").slow(8).icorr(.1).hpf(2000).lpf(6000).gain(.03)

// The farm: the insects fall silent from bar 4, and the wind keeps on
insects: s("insect").slow(4).azimuth(80).distance(5).gain(.06).fadeout(8, 4)
wind: s("wind").slow(8).intensity(.2).gain(.07)

setcpm(96/4)

// The bonfire at the heart of the swamp, and frogs in the reeds behind you
fire: s("fire").slow(4).intensity(.7).density(14).distance(2).gain(.2)
frogs: s("click*4?0.5").lpf(1200).azimuth(160).distance(5).seed("marsh").gain(.1)

// One chant, sung from four places in a ring around you
const chant = note("<[d3 d3 f3 d3] [c3 c3 eb3 d3]>").syl("<[i_a i_a ka thu] [fa tag loo ah]>")
const cultist = (x, type, az) => x.s("voice").voicetype(type).attack(.03).release(.4)
  .azimuth(az).distance(3).room(.4)

front: chant.cultist("bass", 0).gain(.2)
right: chant.late(1/16).cultist("tenor", 90).gain(.16)
behind: chant.late(1/8).cultist("bass", 180).gain(.16)
left: chant.late(3/16).add(12).cultist("alto", -90).gain(.14)

// A frame drum in the middle; toms lean right and earswap throws the steps marked 1 to the left
frame: s("bd ~ ~ bd ~ ~ bd ~").lpf(300).gain(.5)
toms: s("lt*8").speed(.8).ild(8).earswap("0 1 1 0 1 0 0 1").gain(.24)

// A 6 Hz binaural beat in the theta range: each ear is detuned by 3 Hz. Keep it quiet
drone: note("[d2,a2]").slow(4).s("sine").binaural(6)
  .attack(3).sustain(1).release(4).gain(.12)

setcpm(110/4)

// One figure at three speeds, shifted so all three reach the start together every eight bars
// Each note comes from a random place in front of and beside you
figure: n("0 1 4 3 6 5 1 0").scale("C:phrygian dominant").transpose(12)
  .converge(8, 1, 9/8, 5/4)
  .s("triangle").timbre("glass").decay(.2).sustain(0)
  .azimuth(rand.range(-150, 150)).distance(2).seed("angles").room(.4).gain(.1)

// The van der Corput sequence spreads the hats evenly all the way around your head
hats: s("hh*16").hpf(7000).azimuth(ints("vdc", 16).range(-180, 180)).distance(1.5).gain(.2)

// A kick from a sieve of residue classes, kept in the middle
kick: s("bd").struct(sieve("3@0 | 5@2", 16)).shape(.2).gain(.6)

// A second drummer on your right, slipping a sixteenth further every bar
rims: s("rim ~ rim rim ~ rim ~ ~").phase(1/16).azimuth(90).distance(2).gain(.22)

// The room tilts: under about 0.7 ms a delay between the ears leans the drone left, then right
masonry: note("[c2,gb2]").s("sawtooth").itd(sine.range(-.6, .6).slow(8)).lpf(600)
  .attack(1).sustain(1).release(1).gain(.16)

// A centred bass
bass: note("<c2 db2 c2 b1>").struct("x ~ ~ x ~ ~ x ~").s("sine").shape(.2)
  .decay(.3).sustain(.4).release(.1).gain(.4)

setcpm(60/4)

// The forbidden library: nothing is panned, yet the organ's brightness creeps from ear to ear
// A low-pass on each ear alone, sweeping in opposite directions every eight bars
organ: note("<[d3,f3,a3,c4] [bb2,db3,f3,ab3] [g2,bb2,db3,f3] [a2,c#3,e3,g3]>")
  .s("sawtooth").timbre("organ")
  .lcutoff(saw.range(400, 3000).slow(8)).rcutoff(isaw.range(400, 3000).slow(8))
  .attack(.5).sustain(.9).release(1).space("church").gain(.12)

// The pedal holds the roots, centred
pedal: note("<d2 bb1 g1 a1>").s("sawtooth").timbre("organ").lpf(450)
  .attack(.4).sustain(.8).release(1).space("church").gain(.2)

// A candle on your left, a clock on your right, rain beyond the leaded windows
candle: s("fire").slow(4).intensity(.2).density(4).azimuth(-60).distance(2).gain(.12)
clock: s("tick ~ tick ~").azimuth(70).distance(4).gain(.05)
rain: s("rain").slow(4).intensity(.4).occlude(.6).gain(.14)

// Pages turning, now and then
pages: s("~ ~ ~ pink").mask("<0 1 0 0 0 0 1 0>").hpf(2000).lpf(6000)
  .attack(.05).decay(.2).sustain(0).gain(.06)

// Someone reading aloud, right behind your shoulder
reader: s("whisper*4?0.5").syl("<[ne kro no mi] [al haz red ah]>").hpf(900)
  .azimuth(170).distance(1).seed("tome").gain(.08)

setcpm(40/4)

// In his house at R'lyeh dead Cthulhu waits dreaming: a 2 Hz binaural drone, below the 3-30 Hz warning range
drone: note("<c1 c1 ab0 bb0>").slow(4).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.26)

// A drowned choir breathing slowly, heard through stone and water
choir: note("<[c3,eb3,g3] [ab2,c3,eb3] [f2,ab2,c3] [g2,b2,d3]>").slow(2)
  .s("choir").syl("<oo ah oo oh>").occlude(.5).attack(3).release(4).space("church").gain(.22)

// His dreams reach out: glass notes circling your head once every sixteen bars, a little below
dreams: n(irand(6).segment(4)).scale("C:phrygian").transpose(12)
  .degradeBy(.6).seed("dreams")
  .s("triangle").timbre("glass").decay(1.5).sustain(0).release(2)
  .azimuth(saw.range(-180, 180).slow(16)).elevation(-20).distance(3).posglide(.5).room(.6).gain(.08)

// The water pressing in on every side: unrelated brown noise in each ear
pressure: s("brown").slow(8).icorr(.1).lpf(500).gain(.08)

// A sleeper's breath, very slow
breath: s("pink").slow(2).hpf(200).lpf(600).attack(4).release(5).gain(.03)
